import Foundation

// MARK: - On-device relevance math: a faithful port of the server's
// core/scoring.py + core/gating.py + echo gate (pipeline/relevance.py).
// Golden fixtures (Tests/Fixtures/scoring_parity.json, generated by
// eval/export_scoring_fixtures.py from the REAL server functions) pin parity —
// the tuned engine stays one engine conceptually, executed where it is fastest:
// next to the user, offline, zero round-trip.

public struct RelevanceWeights: Sendable, Equatable {
    public var semantic = 0.40
    public var entityOverlap = 0.20
    public var actionability = 0.15
    public var importance = 0.10
    public var recencyDecay = 0.10
    public var speakerMatch = 0.05
    public var recentlyShown = -0.30
    public var dismissedBefore = -0.30
    public init() {}
}

public struct RelevanceConfig: Sendable, Equatable {
    public var windowSeconds: Double = 60
    public var topK = 20
    public var gateThreshold = 0.55
    public var cooldownSeconds: Double = 600
    public var maxCards = 3
    public var cardTtlSeconds: Double = 45
    public var echoSuppress = 0.72
    public var weights = RelevanceWeights()
    public var actionabilityHorizonDays = 14
    public var recencyHalfLifeHours: Double = 168
    public init() {}
}

public struct ScoreFeatures: Sendable, Equatable {
    public var semantic = 0.0
    public var entityOverlap = 0.0
    public var actionability = 0.0
    public var importance = 0.5
    public var recencyDecay = 0.0
    public var speakerMatch = 0.0
    public var recentlyShown = 0.0
    public var dismissedBefore = 0.0
    public init() {}
}

public enum RelevanceMath {
    public static func recencyDecay(recordedAt: Date?, now: Date, halfLifeHours: Double)
        -> Double {
        guard halfLifeHours > 0 else { return 1 }
        guard let recordedAt else { return 0 }
        let ageH = max(0, now.timeIntervalSince(recordedAt) / 3600)
        return pow(0.5, ageH / halfLifeHours)
    }

    /// Port of actionability_score(): imminent events/commitments dominate.
    public static func actionability(type: String, eventStart: Date?, now: Date,
                                     horizonDays: Int, aboutCurrentSpeaker: Bool,
                                     hasDate: Bool) -> Double {
        var score = 0.0
        if let eventStart {
            let delta = eventStart.timeIntervalSince(now)
            if -48 * 3600 <= delta, delta <= Double(horizonDays) * 86_400 {
                score = 1.0
            } else if delta > 0, delta <= 90 * 86_400 {
                score = 0.6
            } else if delta > 90 * 86_400 {
                score = 0.35
            } else {
                score = 0.25   // recent past
            }
        } else if type == "commitment" {
            score = 0.8
        } else if type == "event" || type == "plan" {
            score = hasDate ? 0.4 : 0.2
        }
        if aboutCurrentSpeaker { score = min(1.0, score + 0.4) }
        return score
    }

    public static func speakerMatch(memorySpeakerPresent: Bool,
                                    memorySharesEntityWithSpeaker: Bool) -> Double {
        if memorySpeakerPresent { return 1 }
        if memorySharesEntityWithSpeaker { return 0.5 }
        return 0
    }

    public static func jaccard(_ a: Set<String>, _ b: Set<String>) -> Double {
        guard !a.isEmpty, !b.isEmpty else { return 0 }
        return Double(a.intersection(b).count) / Double(a.union(b).count)
    }

    public static func dismissedScore(dismissCount: Int) -> Double {
        min(1.0, Double(dismissCount) * 0.5)
    }

    public static func computeScore(_ f: ScoreFeatures, _ w: RelevanceWeights) -> Double {
        w.semantic * f.semantic
        + w.entityOverlap * f.entityOverlap
        + w.actionability * f.actionability
        + w.importance * f.importance
        + w.recencyDecay * f.recencyDecay
        + w.speakerMatch * f.speakerMatch
        + w.recentlyShown * f.recentlyShown
        + w.dismissedBefore * f.dismissedBefore
    }

    public static func semanticFromSims(_ windowSim: Double?, _ utteranceSim: Double?)
        -> Double {
        let vals = [windowSim, utteranceSim].compactMap { $0 }.map { max(0, $0) }
        return vals.max() ?? 0
    }

    // MARK: echo gate (≥ echo_suppress of a memory's content words were just spoken →
    // the conversation is relaying it; a card would add nothing)

    static let echoStopWords: Set<String> = Set("""
        a an the and or but if then than that this these those is are was were be been being
        do does did doing i you he she it we they me him her them my your his our their
        of in on at to for with from by as about into over under up down out off again more
        so not no yes just really very too also here there when where why how who whom whose
        what which who will would can could should may might must have has had having am
        its said say says going gonna kinda like well okay oh hey hi ok yeah
        """.split(separator: " ").map(String.init))

    public static func contentTokens(_ text: String) -> Set<String> {
        Set(text.lowercased()
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { !$0.isEmpty && !echoStopWords.contains($0) })
    }

    public static func echoCoverage(memoryText: String, windowText: String) -> Double {
        let mem = contentTokens(memoryText)
        guard !mem.isEmpty else { return 0 }
        let spoken = contentTokens(windowText)
        return Double(mem.intersection(spoken).count) / Double(mem.count)
    }

    // MARK: gating (port of gate_candidates; candidates must be score-sorted desc)

    public struct GateDecision: Sendable, Equatable {
        public var memoryId: String
        public var score: Double
        public var allowed: Bool
        public var reason: String    // ok | below_threshold | cooldown | budget
    }

    public static func gate(_ candidates: [(memoryId: String, score: Double)],
                            now: Date, lastShown: [String: Date],
                            activeCardCount: Int, cfg: RelevanceConfig)
        -> [GateDecision] {
        var decisions: [GateDecision] = []
        var budget = max(0, cfg.maxCards - activeCardCount)
        for (memoryId, score) in candidates {
            if score < cfg.gateThreshold {
                decisions.append(.init(memoryId: memoryId, score: score, allowed: false,
                                       reason: "below_threshold"))
                continue
            }
            if let last = lastShown[memoryId],
               now.timeIntervalSince(last) < cfg.cooldownSeconds {
                decisions.append(.init(memoryId: memoryId, score: score, allowed: false,
                                       reason: "cooldown"))
                continue
            }
            if budget <= 0 {
                decisions.append(.init(memoryId: memoryId, score: score, allowed: false,
                                       reason: "budget"))
                continue
            }
            budget -= 1
            decisions.append(.init(memoryId: memoryId, score: score, allowed: true,
                                   reason: "ok"))
        }
        return decisions
    }

    /// Port of should_expire_card (pin holds; anchor = later of shown/last topic activity)
    public static func shouldExpire(shownAt: Date, now: Date, pinned: Bool,
                                    lastTopicActivity: Date?, cfg: RelevanceConfig)
        -> Bool {
        if pinned { return false }
        let anchor = max(shownAt, lastTopicActivity ?? shownAt)
        return now.timeIntervalSince(anchor) > cfg.cardTtlSeconds
    }
}
